import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;import java.security.SecureRandom;import java.nio.charset.StandardCharsets;
public class AES {public static void main(String[]z)throws Exception{Scanner sc=new Scanner(System.in);System.out.print("Enter text: ");String text=sc.nextLine();byte[] key=new byte[32],iv=new byte[12];SecureRandom sr=new SecureRandom();sr.nextBytes(key);sr.nextBytes(iv);SecretKeySpec sk=new SecretKeySpec(key,"AES");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,sk,new GCMParameterSpec(128,iv));byte[] encrypted=c.doFinal(text.getBytes(StandardCharsets.UTF_8));System.out.println("Key (hex, keep secret): "+hex(key));System.out.println("IV (hex): "+hex(iv));System.out.println("Encrypted: "+hex(encrypted));c.init(Cipher.DECRYPT_MODE,sk,new GCMParameterSpec(128,iv));System.out.println("Decrypted: "+new String(c.doFinal(encrypted),StandardCharsets.UTF_8));}static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format("%02x",x));return s.toString();}}
